import React from 'react';

interface SplitViewLayoutProps {
  sidebar: React.ReactNode;
  content: React.ReactNode;
}

export function SplitViewLayout({ sidebar, content }: SplitViewLayoutProps) {
  return (
    <div className="flex h-screen w-full overflow-hidden bg-gray-50">
      {/* 
        In RTL, flex-row starts from the right.
        sidebar is the AI Assistant (35%), which the spec says should be on the right.
        content is the Editor (65%), which the spec says should be on the left.
        Since dir="rtl", placing sidebar first in the DOM puts it on the right visually.
      */}
      <aside className="w-[35%] h-full flex flex-col border-l border-slate-200 bg-gray-50/50">
        {sidebar}
      </aside>
      
      <main className="w-[65%] h-full flex flex-col">
        {content}
      </main>
    </div>
  );
}
