import React, { useState, useEffect } from 'react';
import { Search, Mic, X, Plus, ClipboardList, ChevronRight } from 'lucide-react';

interface SearchSidebarProps {
  onArticleClick: (articleId: string) => void;
  onSearch: (query: string) => void;
  isLoading: boolean;
  searchResults: any[];
  searchQuery: string;
}

export function SearchSidebar({ onArticleClick, onSearch, isLoading, searchResults, searchQuery }: SearchSidebarProps) {
  const [input, setInput] = useState(searchQuery);
  const [isFocused, setIsFocused] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [loadingStage, setLoadingStage] = useState(0);

  const history = [
    'تعويض العامل عند الفصل التعسفي',
    'أركان عقد الإيجار التجاري',
    'شروط الإعفاء من الضرائب'
  ];

  // Handle Skeleton Stages
  useEffect(() => {
    if (isLoading) {
      setLoadingStage(1);
      const t1 = setTimeout(() => setLoadingStage(2), 500);
      const t2 = setTimeout(() => setLoadingStage(3), 1500);
      return () => { clearTimeout(t1); clearTimeout(t2); };
    } else {
      setLoadingStage(0);
    }
  }, [isLoading]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && e.ctrlKey) {
      setInput(prev => prev + '\n');
    } else if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey) {
      e.preventDefault();
      if (input.trim()) onSearch(input);
    }
  };

  const loadingMessages = [
    '',
    '🔍 جاري البحث في 1,247 مادة قانونية...',
    '⚖️ جاري استخراج المبادئ القضائية العليا...',
    '✍️ جاري صياغة الخلاصة القانونية...'
  ];

  return (
    <div className="flex flex-col h-full bg-white relative">
      {/* Header / History Trail */}
      <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
        <h2 className="font-semibold text-navy-900">البحث الذكي</h2>
        <div className="flex items-center gap-2 max-w-[200px] overflow-hidden">
          <span className="text-xs text-slate-400 whitespace-nowrap">آخر بحث:</span>
          <span className="text-xs text-slate-500 truncate cursor-pointer hover:text-blue-600 transition-colors">
            {history[0]}
          </span>
        </div>
      </div>

      {/* Results Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {isLoading && (
          <div className="animate-fade-in p-5 rounded-lg border border-slate-100 bg-slate-50">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-4 h-4 rounded-full border-2 border-blue-500 border-t-transparent animate-spin"></div>
              <span className="text-sm font-medium text-slate-700 transition-opacity duration-300">
                {loadingMessages[loadingStage]}
              </span>
            </div>
            <div className="space-y-3">
              <div className="h-4 bg-slate-200 rounded animate-pulse w-3/4"></div>
              <div className="h-4 bg-slate-200 rounded animate-pulse w-full"></div>
              <div className="h-4 bg-slate-200 rounded animate-pulse w-5/6"></div>
            </div>
          </div>
        )}

        {!isLoading && searchResults.map(res => (
          <div key={res.id} className="bg-white rounded-lg border border-gray-100 shadow-sm overflow-hidden animate-slide-up origin-top relative">
            <div className="absolute top-3 left-3 bg-green-100 text-green-700 text-xs px-2 py-0.5 rounded-full font-medium">
              ثقة {res.confidence}%
            </div>
            
            <div className="bg-blue-600/5 px-4 py-3 flex items-center gap-2 border-b border-blue-50">
              <ClipboardList className="w-4 h-4 text-navy-900" />
              <h3 className="font-semibold text-navy-900 text-sm">خلاصة الإجابة</h3>
            </div>
            
            <div className="p-4">
              <p className="text-sm leading-relaxed text-slate-700 mb-4 text-justify">
                {res.summary}
              </p>
              
              <hr className="border-slate-100 mb-3" />
              
              <div className="space-y-2">
                <span className="text-xs text-slate-500 block mb-2">الأسانيد القانونية:</span>
                <div className="flex flex-wrap gap-2">
                  {res.citations.map((cit: any) => (
                    <button 
                      key={cit.id}
                      onClick={() => onArticleClick(cit.id)}
                      className="text-xs bg-blue-50 hover:bg-blue-100 text-blue-700 border border-blue-100 px-3 py-1.5 rounded-full transition-colors flex items-center gap-1 group"
                    >
                      {cit.title} - {cit.source}
                      <ChevronRight className="w-3 h-3 opacity-0 -ml-2 group-hover:opacity-100 group-hover:ml-0 transition-all" />
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-gray-100 flex flex-col gap-3">
        {/* Smart Filters */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
          <div className="flex items-center gap-1 bg-blue-50 text-blue-700 border border-blue-100 rounded-full px-3 py-1 text-xs whitespace-nowrap group cursor-pointer hover:bg-blue-100 transition-colors">
            السنة: 2020-2026
            <X className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
          </div>
          <div className="flex items-center gap-1 bg-blue-50 text-blue-700 border border-blue-100 rounded-full px-3 py-1 text-xs whitespace-nowrap group cursor-pointer hover:bg-blue-100 transition-colors">
            نوع: تجاري
            <X className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
          </div>
          <button className="flex items-center gap-1 bg-white border border-dashed border-gray-300 text-gray-500 rounded-full px-3 py-1 text-xs whitespace-nowrap hover:border-gray-400 transition-colors">
            <Plus className="w-3 h-3" />
            إضافة فلتر
          </button>
        </div>

        {/* Search Bar */}
        <div className={`relative flex items-end bg-gray-50 border border-gray-200 rounded-2xl transition-all duration-300 ${
          isFocused ? 'ring-2 ring-blue-500/30 border-blue-400 bg-white' : ''
        }`}>
          <div className="px-3 pb-3 text-blue-600">
            <Search className="w-5 h-5" />
          </div>
          
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
            onKeyDown={handleKeyDown}
            placeholder="اكتب سؤالك القانوني هنا..."
            className="flex-1 w-full py-3 bg-transparent outline-none text-navy-900 text-sm placeholder:text-slate-400 min-h-[48px] max-h-[120px] resize-none leading-relaxed"
            rows={1}
            dir="rtl"
          />
          
          <button 
            onClick={() => setIsListening(!isListening)}
            className="p-3 text-slate-400 hover:text-blue-600 transition-colors self-end"
          >
            <Mic className={`w-5 h-5 ${isListening ? 'animate-pulse text-red-500 hover:text-red-600' : ''}`} />
          </button>
        </div>
        <div className="text-center">
          <span className="text-[10px] text-slate-400">Enter للإرسال • Ctrl+Enter للسطر الجديد</span>
        </div>
      </div>
    </div>
  );
}
